"""Provenance header for every generated file: command, commit, machine, date."""
import datetime
import os
import platform
import subprocess
import sys


def _git(*a):
    root = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
    try:
        return subprocess.check_output(["git", "-C", root, *a], text=True,
                                       stderr=subprocess.DEVNULL).strip()
    except Exception:
        return "unknown"


TRANSCRIPTION = ("transcription: creilly11235/adfgvx-1918 @ e60da03 (Childs log as transcribed "
                 "from the scan; field `printed` unless stated), NOT Schmeh 2017")


def header(prefix, script, transcription=TRANSCRIPTION):
    sha = _git("rev-parse", "HEAD")
    dirty = _git("status", "--porcelain", "--", "search/adfgvx")
    stamp = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    lines = [
        f"Generated by `{os.path.basename(sys.executable)} -I {script}` (run from the repo root)",
        f"commit {sha}{' + uncommitted changes in search/adfgvx' if dirty else ''}",
        f"machine {platform.node()} ({platform.system()} {platform.release()}), "
        f"Python {platform.python_version()}",
        f"date {stamp}",
        transcription,
    ]
    if prefix:
        return "".join(f"{prefix} {l}\n" for l in lines)
    return "".join(f"- {l}\n" for l in lines)
